import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import path from "node:path";

// Object storage for generated PDFs and uploaded logos. Local disk in v1
// (spec §6.1: R2 only when persistent object storage is needed). Keys are
// generated by the app — never taken from user input. Paths are runtime data,
// so the turbopackIgnore hints keep the build from tracing the whole project.

const KEY = /^[a-z0-9][a-z0-9/_.-]{0,200}$/;

function root() {
  return path.resolve(/*turbopackIgnore: true*/ process.env.STORAGE_DIR || path.join(process.cwd(), "storage"));
}

function resolveKey(key: string) {
  if (!KEY.test(key) || key.includes("..")) throw new Error(`Invalid storage key: ${key}`);
  const full = path.resolve(root(), key);
  if (!full.startsWith(root() + path.sep)) throw new Error(`Invalid storage key: ${key}`);
  return full;
}

export async function putObject(key: string, body: Buffer | Uint8Array): Promise<void> {
  const full = resolveKey(key);
  await mkdir(/*turbopackIgnore: true*/ path.dirname(full), { recursive: true });
  await writeFile(/*turbopackIgnore: true*/ full, body);
}

export async function getObject(key: string): Promise<Buffer> {
  return readFile(/*turbopackIgnore: true*/ resolveKey(key));
}

export async function deleteObject(key: string): Promise<void> {
  await rm(/*turbopackIgnore: true*/ resolveKey(key), { force: true });
}
